"mlflow/server/gateway_api.py","what":"in-server gateway API"},{"path":"mlflow/utils/providers.py","what":"provider helpers"}],"shaped_by":"Harutaka Kawamura (human) migrated and renamed it in 2023–24; the 2026 guardrail DB layer by TomuHirata was AI-assisted.","basis":"aa1f044cdf6c","head":"f6ff35427d7e1134a83f8f9d8215d0049149162f","generated_at":"2026-11-15T09:52:30+00:00"}},{"id":"web-ui","name":"React web UI","kind":"module","summary":"Large React/TypeScript SPA served by the server for experiments, traces, registry, gateway, assistant and more.","decision":"Single SPA with shared web-shared packages, Redux plus react-query, Databricks design system, mostly consuming REST proto endpoints.","alternatives":"Server-rendered UI; separate UI repo.","why":"Share components with Databricks product; unclear details.","paths":["mlflow/server/js/src","mlflow/server/js/src/shared/web-shared","mlflow/server/js/src/experiment-tracking","mlflow/server/js/src/gateway","mlflow/server/js/src/model-registry","mlflow/server/js/src/experiment-tracking/components","mlflow/server/js/src/experiment-tracking/pages","mlflow/server/js/src/experiment-tracking/components/experiment-page/components/traces-v4","mlflow/server/js/src/mcp-registry","mlflow/server/js/src/skill-registry","mlflow/server/js/eslint-plugin","mlflow/server/js/config-eslint"],"centrality":3,"clusters":["C5","C7","C10","C14","C15","C16","C17","C19"],"scope":"architectural","history":[{"sha":"d7f5467","date":"2020-08-03","klass":"human","agent":null,"author":"Zhidong Qu","subject":"[Model Version Schema] Add Schema Section in Model Version and Compare Model Version View (#3209)"},{"sha":"916c8c1","date":"2026-03-19","klass":"human","agent":null,"author":"Daniel Lok","subject":"Align lint configs with upstream (#21780)"}],"importance":0.76,"orientation":{"purpose":"The React/TypeScript single-page app the server serves. Users browse experiments, traces, the registry, the gateway and more in it.","decision":"One SPA with s