/js/src/mcp-registry","mlflow/server/js/src/skill-registry"],"centrality":2,"scope":"architectural","history":[],"importance":0.096},{"id":"web-ui/frontend-lint","name":"Frontend lint tooling","kind":"module","summary":"Custom ESLint plugin and presets.","decision":"Repo-local rules.","paths":["mlflow/server/js/eslint-plugin","mlflow/server/js/config-eslint"],"centrality":1,"scope":"architectural","history":[],"importance":0.042}]}]}$u2352cfaa$::jsonb,
    $u1ac53ea8${"units":[{"id":"tracking-store","name":"Tracking & registry metadata stores","kind":"module","summary":"Pluggable store layer persisting experiments, runs, traces, registry, datasets and gateway entities via SQLAlchemy, file store or REST.","decision":"Abstract store interfaces with SQLAlchemy (Alembic-migrated) as the main backend, FileStore legacy, and REST store for remote clients; stores are selected by URI scheme.","alternatives":"Single fixed DB; ORM-free SQL; document store; only file-based storage.","why":"Supports zero-config local use and scalable server deployments; the 2019 store reorg split metadata from artifacts. Trace V3 schema migration moved traces into the stores.","paths":["mlflow/store/tracking","mlflow/store/model_registry","mlflow/store/db","mlflow/store/db_migrations/versions","mlflow/entities","mlflow/store/tracking/sqlalchemy_store.py","mlflow/store/tracking/dbmodels/models.py","mlflow/utils/search_utils.py","mlflow/store/db/utils.py","mlflow/db.py","mlflow/store/tracking/file_store.py","mlflow/store/tracking/abstract_store.py","fs2db","mlflow/entities/model_registry"],"centrality":5,"scope":"architectural","importance":0.733,"history":[{"sha":"60c71fa","date":"2019-10-03","klass":"human","agent":null,"author":"Mani Parkhe","subject":"Reorg of \"mlflow.store\" module and splitting \"tracking\" metadata and \"artifact\" repository submodules (#1900)"},{"sha":"c0ca384","date":"2025-06-23","klass":"human","agent":null,"author":"Yuki Watanabe","subject":"Migrate SQLAlchemyStore to use V3 trace schema (#16381)"},{"sha":"3e1de0c","date":"2025-06-25","klass":"human","agent":null,"author":"Yuki Watanabe","subject":"Migrate FileStore to use V3 trace schema (#16382)"},{"sha":"3f90e98","date":"2025-09-04","klass":"human","agent":null,"author":"Ben Wilson","subject":"Add Evaluation Datasets to MLflow (#17447)"},{"sha":"bdc041e","date":"2026-01-07","klass":"human","agent":null,"author":"Corey Zumar","subject":"[Online Scoring][2/x] Add schema migration for online_scoring_configs table (#19708)"},{"sha":"4daba48","date":"2026-04-03","klass":"assisted","agent":"claude-code","author":"TomuHirata","subject":"Add gateway guardrail DB layer: schema, store methods, and tests (#21960)"}],"parent":null,"orientation":{"purpose":"The persistence layer for experiments, runs, traces, model registry, datasets and gateway entities. It gives the rest of the system one interface to save and query metadata, whatever the backend.","decision":"Abstract store interfaces with SQLAlchemy (Alembic-migrated) as the main backend, a legacy FileStore, and a REST store for remote clients, chosen by URI scheme. Alternatives were a single fixed DB, raw SQL, a document store or files only. The aim was zero-config local use plus scalable servers.","where":[{"path":"mlflow/store/tracking/abstract_store.py","what":"the store interface"},{"path":"mlflow/store/tracking/sqlalchemy_store.py","what":"main SQL backend"},{"path":"mlflow/store/db_migrations/versions","what":"Alembic schema migrations"}],"shaped_by":"Humans alone wrote the decisive commits: Mani Parkhe's 2019 store reorg, then Yuki Watanabe, Ben Wilson and Corey Zumar on V3 traces, datasets and scoring; a 2026 gateway guardrail commit was AI-assisted (TomuHirata).","basis":"10feeee0a03c","head":"f6ff35427d7e1134a83f8f9d8215d0049149162f","generated_at":"2026-11-15T09:52:30+00:00"}},{"id":"tracking-store/sqlalchemy-store","name":"SQLAlchemy store and models","kind":"module","summary":"Main DB-backed tracking store with ORM models and search translation.","decision":"SQLAlchemy ORM with search filter parsing in search_utils.","paths":["mlflow/store/tracking/sqlalchemy_store.py","mlflow/store/tracking/dbmodels/models.py","mlflow/utils/search_utils.py"],"centrality":5,"scope":"architectural","importance":0.276,"history":[],"parent":"tracking-store","orientation":null},{"id":"tracking-store/migrations","name":"Alembic migrations","kind":"boundary","summary":"Schema evolution via many Alembic revisions.","decision":"Every schema change ships an Alembic revision file.","paths":["mlflow/store/db_migrations/versions","mlflow/store/db/utils.py","mlflow/db.py"],"centrality":4,"scope":"architectural","importance":0.174,"history":[],"parent":"tracking-store","orientation":null},{"id":"tracking-store/file-store","name":"FileStore and abstract store","kind":"module","summary":"Filesystem backend and abstract store interface.","decision":"Keep a file backend alongside DB (with an fs2db migration tool).","paths":["mlflow/store/tracking/file_store.py","mlflow/store/tracking/abstract_store.py","fs2db"],"centrality":3,"scope":"architectural","importance":0.138,"history":[],"parent":"tracking-store","orientation":null},{"id":"tracking-store/registry-store","name":"Model/prompt registry store","kind":"module","summary":"Registry persistence for models, prompts and related entities.","decision":"Separate registry store hierarchy sharing the DB infrastructure.","paths":["mlflow/store/model_registry","mlflow/entities/model_registry"],"centrality":3,"scope":"architectural","importance":0.145,"history":[],"parent":"tracking-store","orientation":null},{"id":"rest-server-protos","name":"Tracking server, REST API and protobuf schema","kind":"boundary","summary":"Flask/FastAPI server exposing proto-defined REST endpoints that all clients (Python, Java, R, TS, UI) use.","decision":"Protobuf definitions generate Python/Java messages and drive handler routing in a large handlers.py; server is a Flask app with FastAPI sub-apps.","alternatives":"OpenAPI-first; GraphQL only; gRPC.","why":"Proto-first gives multi-language clients a shared contract; unclear for the Flask+FastAPI mix.","paths":["mlflow/server/handlers.py","mlflow/protos","mlflow/server/__init__.py","mlflow/server/fastapi_app.py","dev/generate_protos.py","mlflow/store/tracking/rest_store.py","mlflow/utils/rest_utils.py"],"centrality":5,"scope":"architectural","importance":0.691,"history":[{"sha":"60c71fa","date":"2019-10-03","klass":"human","agent":null,"author":"Mani Parkhe","subject":"Reorg of \"mlflow.store\" module and splitting \"tracking\" metadata and \"artifact\" repository submodules (#1900)"},{"sha":"d8d92ca","date":"2025-05-01","klass":"human","agent":null,"author":"Yuki Watanabe","subject":"Merge Tracing SDK feature branch (#15561)"}],"parent":null,"orientation":{"purpose":"The tracking server that exposes the REST API all clients use. A shared protobuf schema defines the endpoints and messages.","decision":"Protobuf definitions generate the Python and Java messages and drive routing in the large handlers.py. The server is a Flask app with FastAPI sub-apps. OpenAPI-first, GraphQL and gRPC were not chosen. Proto-first gives every language one contract; the code does not show why Flask and FastAPI are mixed.","where":[{"path":"mlflow/server/handlers.py","what":"endpoint handlers and routing"},{"path":"mlflow/protos","what":"proto definitions"},{"path":"mlflow/server/fastapi_app.py","what":"FastAPI layer"}],"shaped_by":"Human-written: Mani Parkhe's 2019 store reorg and Yuki Watanabe's 2025 tracing feature-branch merge.","basis":"21496ad8ab3f","head":"f6ff35427d7e1134a83f8f9d8215d0049149162f","generated_at":"2026-11-15T09:52:30+00:00"}},{"id":"tracking-fluent-client","name":"Python tracking client and fluent API","kind":"module","summary":"mlflow.start_run/log_* fluent API over MlflowClient that picks stores via URI.","decision":"Fluent global-state API layered on a client and tracking-service/registry-service wrappers.","paths":["mlflow/tracking","mlflow/__init__.py","mlflow/environment_variables.py"],"centrality":5,"scope":"architectural","importance":0.717,"history":[{"sha":"7a69ba6","date":"2018-06-05","klass":"human","agent":null,"author":"Matei Zaharia","subject":"Initial commit of mlflow"}],"parent":null,"orientation":{"purpose":"The Python client API users call directly, such as start_run and log_*. It hides store selection behind URIs.","decision":"A fluent API with global active-run state sits on top of MlflowClient and the tracking and registry service wrappers. Neither the code nor the history shows what alternatives were considered or why this was chosen.","where":[{"path":"mlflow/tracking","what":"fluent API, client and service wrappers"},{"path":"mlflow/__init__.py","what":"top-level exports"},{"path":"mlflow/environment_variables.py","what":"configuration variables"}],"shaped_by":"Human-written: Matei Zaharia's initial commit in June 2018.","basis":"68b9b22c05a8","head":"f6ff35427d7e1134a83f8f9d8215d0049149162f","generated_at":"2026-11-15T09:52:30+00:00"}},{"id":"tracing","name":"Tracing SDK and exporters","kind":"module","summary":"OpenTelemetry-based tracing: fluent decorators, span processors, exporters to MLflow/OTLP, trace entities.","decision":"Built on OpenTelemetry with a private tracer provider and MLflow-specific processors/exporters; V3 trace schema.","alternatives":"Custom span model; global OTel provider.","why":"OTel compatibility and isolation from user instrumentation; the SDK was merged from a feature branch.","paths":["mlflow/tracing","mlflow/entities/span.py","mlflow/entities/trace.py","mlflow/server/otel_api.py","mlflow/tracing/provider.py","mlflow/tracing/fluent.py","mlflow/tracing/processor","mlflow/tracing/export","mlflow/tracing/client.py","mlflow/store/tracking/databricks_rest_store.py","mlflow/tracing/otel"],"centrality":5,"scope":"architectural","importance":0.669,"history":[{"sha":"d8d92ca","date":"2025-05-01","klass":"human","agent":null,"author":"Yuki Watanabe","subject":"Merge Tracing SDK feature branch (#15561)"},{"sha":"f790471","date":"2024-06-25","klass":"human","agent":null,"author":"Yuki Watanabe","subject":"Refactor `@trace_disabled` implementation (#12285)"},{"sha":"c55516d","date":"2025-01-23","klass":"human","agent":null,"author":"Yuki Watanabe","subject":"Support timeout for a trace (#14288)"},{"sha":"0f4a5bb","date":"2025-07-16","klass":"human","agent":null,"author":"Yuki Watanabe","subject":"Update build scripts to handle mlflow-tracing (#15860)"}],"parent":null,"orientation":{"purpose":"The SDK that records LLM and app execution as traces. It offers decorators, span processing and export to MLflow or OTLP backends.","decision":"Built on OpenTelemetry with a private tracer provider and MLflow-specific processors and exporters, using the V3 trace schema. Alternatives were a custom span model or the global OTel provider. The aims were OTel compatibility and isolation from user instrumentation.","where":[{"path":"mlflow/tracing/fluent.py","what":"decorators and fluent API"},{"path":"mlflow/tracing/provider.py","what":"private tracer provider"},{"path":"mlflow/tracing/export","what":"exporters"}],"shaped_by":"Human-written, mainly by Yuki Watanabe: the 2025 feature-branch merge, with earlier and later refinements.","basis":"21fcdd615182","head":"f6ff35427d7e1134a83f8f9d8215d0049149162f","generated_at":"2026-11-15T09:52:30+00:00"}},{"id":"tracing/provider-fluent","name":"Provider and fluent API","kind":"module","summary":"Tracer provider setup and @trace/start_span APIs.","decision":"Isolated OTel provider with enable/disable.","paths":["mlflow/tracing/provider.py","mlflow/tracing/fluent.py"],"centrality":5,"scope":"architectural","importance":0.228,"history":[],"parent":"tracing","orientation":null},{"id":"tracing/exporters-processors","name":"Processors and exporters","kind":"module","summary":"Convert spans to traces and ship them to stores/OTLP.","decision":"Pluggable processors per destination (MLflow, Databricks, inference table, OTel).","paths":["mlflow/tracing/processor","mlflow/tracing/export"],"centrality":4,"scope":"architectural","importance":0.181,"history":[],"parent":"tracing","orientation":null},{"id":"tracing/trace-client","name":"Trace client and stores","kind":"module","summary":"Client for trace search/log across backends.","decision":"Separate TracingClient wrapping stores.","paths":["mlflow/tracing/client.py","mlflow/store/tracking/databricks_rest_store.py"],"centrality":4,"scope":"architectural","importance":0.143,"history":[],"parent":"tracing","orientation":null},{"id":"tracing/otel-translation","name":"OTel semantic translation","kind":"module","summary":"Maps external OTel/GenAI semconv attributes to MLflow spans.","decision":"Translator classes per convention.","paths":["mlflow/tracing/otel","mlflow/server/otel_api.py"],"centrality":3,"scope":"architectural","importance":0.116,"history":[],"parent":"tracing","orientation":null},{"id":"models-pyfunc","name":"Model flavors, pyfunc and serving","kind":"module","summary":"MLmodel packaging, signatures, pyfunc generic interface, scoring server and environment capture.","decision":"Flavor-per-library modules converge on pyfunc; models serve through a gunicorn/FastAPI scoring server with captured requirements.","alternatives":"ONNX-only; single serialization format.","why":"Framework-agnostic deployment; serving moved to gunicorn in 2019.","paths":["mlflow/pyfunc","mlflow/models","mlflow/types","mlflow/utils/environment.py","mlflow/utils/requirements_utils.py","mlflow/sagemaker","mlflow/deployments"],"centrality":5,"scope":"architectural","importance":0.787,"history":[{"sha":"9a8ee6c","date":"2019-05-24","klass":"human","agent":null,"author":"tomasatdatabricks","subject":"Switch to gunicorn for serving of python models. (#1322)"},{"sha":"fa1c06c","date":"2025-02-18","klass":"human","agent":null,"author":"Aravind Segu","subject":"Introduce User Auth Policy for Pyfunc Models (#14538)"}],"parent":null,"orientation":{"purpose":"Packages models in the MLmodel format with signatures and environment capture. The generic pyfunc interface and scoring server let any model be loaded and served.","decision":"Each library gets a flavor module, and all flavors converge on pyfunc. Serving uses a gunicorn/FastAPI scoring server with captured requirements. ONNX-only or a single serialization format were not chosen, to keep deployment fra