 reasons beyond that are unclear.","where":[{"path":"mlflow/gateway","what":"providers and gateway app"},{"path":"mlflow/server/gateway_api.py","what":"in-server gateway API"},{"path":"mlflow/utils/providers.py","what":"provider helpers"}],"shaped_by":"Harutaka Kawamura (human) migrated and renamed it in 2023–24; the 2026 guardrail DB layer by TomuHirata was AI-assisted.","basis":"aa1f044cdf6c","head":"f6ff35427d7e1134a83f8f9d8215d0049149162f","generated_at":"2026-11-15T09:52:30+00:00"}},{"id":"web-ui","name":"React web UI","kind":"module","summary":"Large React/TypeScript SPA served by the server for experiments, traces, registry, gateway, assistant and more.","decision":"Single SPA with shared web-shared packages, Redux plus react-query, Databricks design system, mostly consuming REST proto endpoints.","alternatives":"Server-rendered UI; separate UI repo.","why":"Share components with Databricks product; unclear details.","paths":["mlflow/server/js/src","mlflow/server/js/src/shared/web-shared","mlflow/server/js/src/experiment-tracking","mlflow/server/js/src/gateway","mlflow/server/js/src/model-registry","mlflow/server/js/src/experiment-tracking/components","mlflow/server/js/src/experiment-tracking/pages","mlflow/server/js/src/experiment-tracking/components/experiment-page/components/traces-v4","mlflow/server/js/src/mcp-registry","mlflow/server/js/src/skill-registry","mlflow/server/js/eslint-plugin","mlflow/server/js/config-eslint"],"centrality":3,"scope":"architectural","importance":0.76,"history":[{"sha":"d7f5467","date":"2020-08-03","klass":"human","agent":null,"author":"Zhidong Qu","subject":"[Model Version Schema] Add Schema Section in Model Version and Compare Model Version View (#3209)"},{"sha":"916c8c1","date":"2026-03-19","klass":"human","agent":null,"author":"Daniel Lok","subject":"Align lint configs with upstream (#21780)"}],"parent":null,"orientation":{"purpose":"The React/TypeScript single-page app the server serves. Users browse experiments, traces, the registry, the gateway and more in it.","decision":"One SPA with shared web-shared packages, Redux plus react-query, and the Databricks design system, mostly consuming the REST proto endpoints. A server-rendered UI or a separate UI repo were not chosen. It shares components with the Databricks product; other details are unclear.","where":[{"path":"mlflow/server/js/src/experiment-tracking","what":"experiment and trace UI"},{"path":"mlflow/server/js/src/shared/web-shared","what":"shared components"},{"path":"mlflow/server/js/src/model-registry","what":"registry UI"}],"shaped_by":"Human-written: Zhidong Qu (2020 model version schema UI) and Daniel Lok (2026 lint config alignment).","basis":"c72b20c3e4aa","head":"f6ff35427d7e1134a83f8f9d8215d0049149162f","generated_at":"2026-11-15T09:52:30+00:00"}},{"id":"web-ui/experiment-ui","name":"Experiment and runs UI","kind":"module","summary":"Experiment pages, run comparison, charts, artifacts.","decision":"Redux-era components plus hooks.","paths":["mlflow/server/js/src/experiment-tracking/components","mlflow/server/js/src/experiment-tracking/pages"],"centrality":4,"scope":"architectural","importance":0.3,"history":[],"parent":"web-ui","orientation":null},{"id":"web-ui/trace-ui","name":"Trace explorer and tables","kind":"module","summary":"Model trace explorer, GenAI traces table, traces v4.","decision":"Shared web-shared library.","paths":["mlflow/server/js/src/shared/web-shared","mlflow/server/js/src/experiment-tracking/components/experiment-page/components/traces-v4"],"centrality":4,"scope":"architectural","importance":0.22,"history":[],"parent":"web-ui","orientation":null},{"id":"web-ui/gateway-ui","name":"Gateway UI","kind":"module","summary":"Endpoint, key, budget, guardrail forms.","decision":"react-hook-form based.","paths":["mlflow/server/js/src/gateway"],"centrality":2,"scope":"architectural","importance":0.102,"history":[],"parent":"web-ui","orientation":null},{"id":"web-ui/registry-ui","name":"Registry UIs","kind":"module","summary":"Model, prompt, MCP and skill registries.","decision":"Per-registry feature folders.","paths":["mlflow/server/js/src/model-registry","mlflow/server/js/src/mcp-registry","mlflow/server/js/src/skill-registry"],"centrality":2,"scope":"architectural","importance":0.096,"history":[],"parent":"web-ui","orientation":null},{"id":"web-ui/frontend-lint","name":"Frontend lint tooling","kind":"module","summary":"Custom ESLint plugin and presets.","decision":"Repo-local rules.","paths":["mlflow/server/js/eslint-plugin","mlflow/server/js/config-eslint"],"centrality":1,"scope":"architectural","importance":0.042,"history":[],"parent":"web-ui","orientation":null}],"connections":[["ai-gateway","artifact-repos","uses",4.0],["ai-gateway","autologging-integrations","uses",1.0],["ai-gateway","genai-eval-scorers","uses",5.0],["ai-gateway","models-pyfunc","uses",6.0],["ai-gateway","platform-config-packaging","uses",11.0],["ai-gateway","rest-server-protos","uses",5.5],["ai-gateway","tracing","uses",10.5],["ai-gateway","tracking-fluent-client","uses",12.5],["ai-gateway","tracking-store","uses",22.0],["artifact-repos","platform-config-packaging","uses",14.5],["artifact-repos","rest-server-protos","uses",38.0],["artifact-repos","tracing","uses",5.5],["artifact-repos","tracking-fluent-client","uses",20.0],["artifact-repos","tracking-store","uses",31.0],["auth-security","ai-gateway","uses",2.0],["auth-security","artifact-repos","uses",3.0],["auth-security","genai-eval-scorers","uses",2.0],["auth-security","platform-config-packaging","uses",4.0],["auth-security","rest-server-protos","uses",16.0],["auth-security","tracing","uses",3.5],["auth-security","tracking-fluent-client","uses",6.0],["auth-security","tracking-store","uses",5.5],["autologging-integrations","ai-gateway","uses",3.5],["autologging-integrations","artifact-repos","uses",3.0],["autologging-integrations","genai-eval-scorers","uses",5.0],["autologging-integrations","models-pyfunc","uses",57.5],["autologging-integr